mapper.select:
select count(*)
from (
    select sp.paymentid
    from studycafe_pay sp 
    join usertb utb on sp.user_idx = utb.user_idx
    where utb.user_idx=#{user_idx} 
      and sp.pay_status='PAID'
    union all
    select paynum
    from membership_payment
    where user_idx=#{user_idx} 
      and membership_idx=2
)
